class Solution:
    def camelMatch(self, queries: List[str], pattern: str) -> List[bool]:
        def match(q, p):
            @lru_cache(None)
            def go(i, j):
                if i == len(q):
                    return j == len(p)
                if j < len(p) and q[i] == p[j] and go(i + 1, j + 1):
                    return True
                if q[i].islower() and go(i + 1, j):
                    return True
                return False
            return go(0, 0)
        return [match(q, pattern) for q in queries]

