class Solution {
public:
    vector<bool> camelMatch(vector<string>& queries, string pattern) {
        vector<bool> res;
        for (auto& q : queries) res.push_back(match(q, pattern));
        return res;
    }
private:
    bool match(const string& q, const string& p) {
        int n = q.size(), m = p.size();
        vector<vector<char>> dp(n + 1, vector<char>(m + 1, -1));
        function<bool(int,int)> go = [&](int i, int j) -> bool {
            if (i == n) return j == m;
            if (dp[i][j] != -1) return dp[i][j];
            bool ok = false;
            if (j < m && q[i] == p[j]) ok = go(i + 1, j + 1);
            if (!ok && islower(q[i])) ok = go(i + 1, j);
            return dp[i][j] = ok;
        };
        return go(0, 0);
    }
};

