class Solution {
    public List<Boolean> camelMatch(String[] queries, String pattern) {
        List<Boolean> res = new ArrayList<>();
        for (String q : queries) res.add(match(q, pattern));
        return res;
    }
    private boolean match(String q, String p) {
        int n = q.length(), m = p.length();
        Boolean[][] memo = new Boolean[n + 1][m + 1];
        return go(q, p, 0, 0, memo);
    }
    private boolean go(String q, String p, int i, int j, Boolean[][] memo) {
        if (i == q.length()) return j == p.length();
        if (memo[i][j] != null) return memo[i][j];
        boolean ok = false;
        if (j < p.length() && q.charAt(i) == p.charAt(j)) ok = go(q, p, i + 1, j + 1, memo);
        if (!ok && Character.isLowerCase(q.charAt(i))) ok = go(q, p, i + 1, j, memo);
        return memo[i][j] = ok;
    }
}

