class Solution {
public:
    vector<bool> camelMatch(vector<string>& queries, string pattern) {
        vector<bool> res;
        for (auto& q : queries) {
            size_t j = 0;
            bool ok = true;
            for (char c : q) {
                if (j < pattern.size() && c == pattern[j]) j++;
                else if (isupper(c)) { ok = false; break; }
            }
            res.push_back(ok && j == pattern.size());
        }
        return res;
    }
};

